/**
 * Node.js port of dataset/bencoder/test4.py
 *
 *   import argparse
 *   import bencoder
 *
 *   parser = argparse.ArgumentParser()
 *   parser.add_argument('--a', type=str, required=True)
 *   args = parser.parse_args()
 *
 *   result = bencoder.decode(args.a.encode('ascii'))  # Decode bencoded string
 *   print(result)
 *
 * Run it exactly like the reference executable:
 *   node test4.mjs --a '9:value'      ->  b'value'
 */

import { ArgumentParser, SystemExit } from './lib/argparse/index.mjs';
import { decode } from './lib/bencoder/index.mjs';
import { encodeAscii } from './lib/codecs/ascii.mjs';
import { pyStr } from './lib/pytypes/repr.mjs';
import {
  CARET_DECODE_CALL,
  CARET_ENCODE_CALL,
  PyException,
  PyUnicodeEncodeError,
  formatTraceback,
} from './lib/runtime/exceptions.mjs';
import { exitWith, printLine, writeStderr } from './lib/runtime/stdio.mjs';

function main() {
  const parser = new ArgumentParser();
  parser.addArgument('--a', { required: true });
  const args = parser.parseArgs(process.argv.slice(2));

  const result = decode(encodeAscii(args.a));
  printLine(pyStr(result));
}

try {
  main();
} catch (error) {
  if (error instanceof SystemExit) {
    exitWith(error.status);
  } else if (error instanceof PyException) {
    // An uncaught Python exception: traceback on stderr, exit status 1. The
    // underlined sub-expression depends on which call raised.
    const caret = error instanceof PyUnicodeEncodeError ? CARET_ENCODE_CALL : CARET_DECODE_CALL;
    writeStderr(formatTraceback(error, caret));
    exitWith(1);
  } else {
    throw error;
  }
}

/**
 * `str.encode('ascii')` with CPython's strict error handler.
 *
 * On the first run of non-ASCII characters CPython raises
 * `UnicodeEncodeError`, whose message reports code-point *string* indices —
 * an astral character counts as one position even though JS stores it as a
 * surrogate pair.
 */

import { Bytes } from '../pytypes/bytestring.mjs';
import { PyUnicodeEncodeError } from '../runtime/exceptions.mjs';

/** How CPython spells the offending character inside the error message. */
function escapeCodePoint(codePoint) {
  if (codePoint <= 0xff) return `\\x${codePoint.toString(16).padStart(2, '0')}`;
  if (codePoint <= 0xffff) return `\\u${codePoint.toString(16).padStart(4, '0')}`;
  return `\\U${codePoint.toString(16).padStart(8, '0')}`;
}

const REASON = 'ordinal not in range(128)';

/**
 * @param {string} text
 * @returns {Bytes}
 */
export function encodeAscii(text) {
  // Code points, so that positions match Python string indices.
  const codePoints = [...text].map((ch) => ch.codePointAt(0));

  let start = -1;
  for (let index = 0; index < codePoints.length; index += 1) {
    if (codePoints[index] >= 0x80) {
      start = index;
      break;
    }
  }

  if (start === -1) return new Bytes(text);

  // CPython reports the whole maximal run of unencodable characters.
  let end = start + 1;
  while (end < codePoints.length && codePoints[end] >= 0x80) end += 1;

  const detail =
    end - start === 1
      ? `'ascii' codec can't encode character '${escapeCodePoint(codePoints[start])}' in position ${start}: ${REASON}`
      : `'ascii' codec can't encode characters in position ${start}-${end - 1}: ${REASON}`;
  throw new PyUnicodeEncodeError(detail);
}

